import React, { useEffect, useState, useCallback } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";

const Post = () => {
  const { id } = useParams();
  const [postobject, setpostobject] = useState({});
  const [comments, setcomments] = useState([]);
  const [newcomment, setnewcomment] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    setLoading(true);
    setError(null);

    Promise.all([
      axios.get(`http://localhost:3003/posts/byid/${id}`),
      axios.get(`http://localhost:3003/comments/${id}`),
    ])
      .then(([postRes, commentsRes]) => {
        setpostobject(postRes.data);
        setcomments(commentsRes.data);
      })
      .catch((err) => {
        console.error(err);
        setError("Failed to load post.");
      })
      .finally(() => setLoading(false));
  }, [id]);

  const addcomment = useCallback(() => {
    if (!newcomment.trim()) return;

    axios
      .post(
        "http://localhost:3003/comments",
        { commentbody: newcomment, postid: id },
        { headers: { accesstoken: sessionStorage.getItem("accesstoken") } },
      )
      .then((response) => {
        if (response.data.error) {
          console.log(response.data.error);
        } else {
          // use whatever the server returns, falling back to a temp object
          const commenttoadd = response.data.comment ?? { commentbody: newcomment };
          setcomments((prev) => [...prev, commenttoadd]);
          setnewcomment("");
        }
      })
      .catch((err) => console.error(err));
  }, [newcomment, id]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div>{error}</div>;

  return (
    <div className="postPage">
      <div className="leftSide">
        <div className="post" id="individual">
          <div className="title">{postobject.title}</div>
          <div className="body">{postobject.posttext}</div>
          <div className="footer">{postobject.username}</div>
        </div>
      </div>
      <div className="rightSide">
        <div className="addCommentContainer">
          <input
            type="text"
            placeholder="Comment........"
            value={newcomment}
            autoCapitalize="off"
            onChange={(event) => setnewcomment(event.target.value)}
            onKeyDown={(event) => event.key === "Enter" && addcomment()}
          />
          <button onClick={addcomment}>Add Comment</button>
        </div>
        <div className="listOfComments">
          {comments.map((comment) => (
            <div key={comment.id ?? comment._id ?? comment.commentbody} className="comment">
              {comment.commentbody}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Post;
